package com.gatecraft.game;

import android.content.Context;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.Paint;
import android.graphics.RectF;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

final class HeroesCraftView extends BaseArcadeView {
  static final class Node{int x,y,type;boolean taken;Node(int x,int y,int t){this.x=x;this.y=y;type=t;}}
  private int page=0,hx=2,hy=6,iron=2,cement=1,tools=1,gold=120,score,shop=1,weld=0,truck=0,ownHp=170,enemyHp=160,turn=0;
  private final List<Node> nodes=new ArrayList<Node>();private final Random rnd=new Random(721);
  private final RectF up=new RectF(62,391,132,461),down=new RectF(62,466,132,536),left=new RectF(0,466,70,536),right=new RectF(136,466,206,536),town=new RectF(730,430,832,496),combat=new RectF(840,430,950,496),action=new RectF(744,358,948,418);
  HeroesCraftView(Context c,GateCraftGame o){super(c,o);for(int i=0;i<16;i++)nodes.add(new Node(2+rnd.nextInt(9),1+rnd.nextInt(7),rnd.nextInt(4)));}
  @Override public int score(){return score;}@Override public void restart(){page=0;ownHp=170;enemyHp=160;turn=0;invalidate();}
  @Override void updateGame(float dt){}
  @Override void drawGame(Canvas c){if(page==0)drawMap(c);else if(page==1)drawTown(c);else drawCombat(c);}
  private void drawFrame(Canvas c,String title){fill(c,Color.rgb(10,9,11),0,0,960,540);fill(c,Color.rgb(117,81,41),0,74,960,540);for(int x=0;x<960;x+=24){fill(c,Color.rgb(66,43,25),x,74,x+8,540);}fill(c,Color.rgb(29,24,19),18,86,942,522);stroke(c,Color.rgb(222,190,116),4,18,86,942,522);fill(c,Color.rgb(49,32,21),0,0,960,74);text(c,title,32,48,28,Color.rgb(248,219,147),Paint.Align.LEFT,true);text(c,"Fe "+iron+"   Cem "+cement+"   Tool "+tools+"   Gold "+gold,520,46,17,Color.WHITE,Paint.Align.LEFT,true);}
  private void drawMap(Canvas c){drawFrame(c,"HEROES OF CRAFT & GATES");float oxm=266,oym=116,tw=58,th=30;for(int y=0;y<9;y++)for(int x=0;x<12;x++){int col=((x+y)%5==0)?Color.rgb(50,105,54):Color.rgb(61,122,61);if(y>6&&x<3)col=Color.rgb(42,92,130);diamond(c,oxm+(x-y)*tw/2,oym+(x+y)*th/2,tw,th,col,Color.rgb(31,65,36));if(col!=Color.rgb(42,92,130)&&((x*7+y*11)%9==0))tree(c,oxm+(x-y)*tw/2,oym+(x+y)*th/2-11);}for(Node n:nodes)if(!n.taken){float cx=oxm+(n.x-n.y)*tw/2,cy=oym+(n.x+n.y)*th/2-13;drawNode(c,cx,cy,n.type);}float heroX=oxm+(hx-hy)*tw/2,heroY=oym+(hx+hy)*th/2-20;hero(c,heroX,heroY);building(c,oxm+(8-2)*tw/2,oym+(8+2)*th/2-35,Color.rgb(150,147,133));text(c,t("MŰHELY","WORKSHOP","WERKSTATT","TALLER","ATELIER","工坊","OFFICINA","OFICINA","WARSZTAT","WERKPLAATS","ATELIER","МАСТЕРСКАЯ"),724,336,13,Color.WHITE,Paint.Align.CENTER,true);arcadeButton(c,up,"▲",Color.rgb(76,80,112),false);arcadeButton(c,down,"▼",Color.rgb(76,80,112),false);arcadeButton(c,left,"◀",Color.rgb(76,80,112),false);arcadeButton(c,right,"▶",Color.rgb(76,80,112),false);arcadeButton(c,town,t("MŰHELY","TOWN","WERKSTATT","TALLER","ATELIER","工坊","OFFICINA","OFICINA","WARSZTAT","WERKPLAATS","ATELIER","МАСТЕРСКАЯ"),Color.rgb(121,77,33),false);arcadeButton(c,combat,t("HARC","COMBAT","KAMPF","COMBATE","COMBAT","战斗","LOTTA","COMBATE","WALKA","GEVECHT","LUPTĂ","БОЙ"),Color.rgb(131,48,44),false);}
  private void tree(Canvas c,float x,float y){fill(c,Color.rgb(74,46,25),x-4,y,x+4,y+21);fill(c,Color.rgb(27,73,39),x-13,y-17,x+13,y+3);fill(c,Color.rgb(42,103,48),x-9,y-24,x+8,y-6);fill(c,Color.rgb(83,128,55),x-3,y-27,x+10,y-12);}
  private void drawNode(Canvas c,float x,float y,int t){if(t==0){fill(c,Color.rgb(128,137,146),x-13,y-8,x+13,y+8);fill(c,Color.rgb(205,211,214),x-9,y-11,x+5,y-5);}else if(t==1){fill(c,Color.rgb(196,187,154),x-10,y-12,x+10,y+10);text(c,"C",x,y+6,13,Color.rgb(80,62,40),Paint.Align.CENTER,true);}else if(t==2){fill(c,Color.rgb(128,75,34),x-13,y-9,x+13,y+10);fill(c,Color.rgb(205,154,52),x-10,y-7,x+10,y-3);}else{fill(c,Color.rgb(74,98,119),x-14,y-12,x+14,y+11);fill(c,Color.rgb(210,184,66),x-4,y-16,x+5,y-6);}}
  private void hero(Canvas c,float x,float y){fill(c,Color.rgb(36,69,128),x-8,y-20,x+9,y+4);fill(c,Color.rgb(231,190,132),x-6,y-30,x+7,y-19);fill(c,Color.rgb(172,126,42),x-9,y-34,x+10,y-28);fill(c,Color.rgb(48,40,37),x-7,y+3,x-1,y+14);fill(c,Color.rgb(48,40,37),x+2,y+3,x+8,y+14);fill(c,Color.rgb(200,204,206),x+9,y-14,x+20,y-10);}
  private void building(Canvas c,float x,float y,int col){fill(c,Color.rgb(69,55,45),x-35,y-8,x+35,y+28);fill(c,col,x-30,y-35,x+30,y+25);for(int i=-24;i<=24;i+=16)fill(c,Color.rgb(85,88,91),x+i,y-45,x+i+10,y-30);fill(c,Color.rgb(50,45,42),x-6,y+2,x+7,y+25);fill(c,Color.rgb(168,119,45),x-20,y-21,x-8,y-9);fill(c,Color.rgb(168,119,45),x+8,y-21,x+20,y-9);}
  private void drawTown(Canvas c){drawFrame(c,t("MŰHELYFEJLESZTÉS","WORKSHOP DEVELOPMENT","WERKSTATTAUSBAU","DESARROLLO DEL TALLER","DÉVELOPPEMENT ATELIER","工坊发展","SVILUPPO OFFICINA","DESENVOLVIMENTO DA OFICINA","ROZWÓJ WARSZTATU","WERKPLAATS ONTWIKKELING","DEZVOLTARE ATELIER","РАЗВИТИЕ МАСТЕРСКОЙ"));fill(c,Color.rgb(60,78,55),42,112,918,506);for(int y=112;y<506;y+=30)for(int x=42;x<918;x+=46)diamond(c,x,y,46,24,((x+y)/10)%2==0?Color.rgb(65,103,64):Color.rgb(58,93,59),Color.rgb(42,66,43));building(c,210,285,Color.rgb(150,132,101));building(c,470,245,Color.rgb(109,120,128));building(c,725,292,Color.rgb(122,95,66));text(c,t("KIS MŰHELY","SMALL WORKSHOP","KLEINE WERKSTATT","TALLER PEQUEÑO","PETIT ATELIER","小工坊","PICCOLA OFFICINA","OFICINA PEQUENA","MAŁY WARSZTAT","KLEINE WERKPLAATS","ATELIER MIC","МАЛАЯ МАСТЕРСКАЯ")+" Lv"+shop,210,350,15,Color.WHITE,Paint.Align.CENTER,true);text(c,t("HEGESZTŐ SZEKCIÓ","WELDING SECTION","SCHWEISSBEREICH","SECCIÓN SOLDADURA","ZONE SOUDAGE","焊接区","SEZIONE SALDATURA","SEÇÃO DE SOLDA","SEKCJA SPAWANIA","LASAFDELING","SECȚIE SUDURĂ","СВАРОЧНЫЙ ЦЕХ")+" Lv"+weld,470,350,15,Color.WHITE,Paint.Align.CENTER,true);text(c,t("TEHERAUTÓ BEÁLLÓ","TRUCK BAY","LKW-PLATZ","ZONA CAMIÓN","AIRE CAMION","卡车区","AREA CAMION","ÁREA DO CAMINHÃO","STANOWISKO CIĘŻARÓWKI","TRUCKVAK","ZONĂ CAMION","СТОЯНКА ГРУЗОВИКА")+" Lv"+truck,725,350,15,Color.WHITE,Paint.Align.CENTER,true);arcadeButton(c,action,t("FEJLESZTÉS: 100 GOLD","UPGRADE: 100 GOLD","AUSBAU: 100 GOLD","MEJORA: 100 GOLD","AMÉLIORER: 100 GOLD","升级: 100 GOLD","MIGLIORA: 100 GOLD","MELHORAR: 100 GOLD","ULEPSZ: 100 GOLD","UPGRADE: 100 GOLD","UPGRADE: 100 GOLD","УЛУЧШИТЬ: 100 GOLD"),Color.rgb(106,70,31),false);}
  private void drawCombat(Canvas c){drawFrame(c,t("MEGRENDELÉS / HARC","CONTRACT / COMBAT","AUFTRAG / KAMPF","ENCARGO / COMBATE","CHANTIER / COMBAT","订单 / 战斗","COMMESSA / LOTTA","SERVIÇO / COMBATE","ZLECENIE / WALKA","OPDRACHT / GEVECHT","LUCRARE / LUPTĂ","ЗАКАЗ / БОЙ"));fill(c,Color.rgb(50,68,53),40,108,920,506);for(int gy=0;gy<5;gy++)for(int gx=0;gx<8;gx++)diamond(c,150+gx*94+(gy%2)*47,178+gy*58,96,54,((gx+gy)%2==0?Color.rgb(79,96,64):Color.rgb(69,87,58)),Color.rgb(41,53,38));for(int i=0;i<3;i++)unit(c,180+i*92,350-i*35,i,false);for(int i=0;i<3;i++)unit(c,720-i*88,230+i*40,i,true);bar(c,110,122,ownHp,170,Color.rgb(60,180,78));bar(c,600,122,enemyHp,160,Color.rgb(190,58,49));text(c,t("SAJÁT CSAPAT","YOUR CREW","DEIN TEAM","TU EQUIPO","VOTRE ÉQUIPE","你的队伍","LA TUA SQUADRA","SUA EQUIPE","TWOJA EKIPA","JOUW TEAM","ECHIPA TA","ВАША БРИГАДА"),110,114,14,Color.WHITE,Paint.Align.LEFT,true);text(c,t("KÓKLER BRIGÁD","RIVAL CREW","PFUSCHER-TEAM","BANDA RIVAL","ÉQUIPE RIVALE","对手队伍","SQUADRA RIVALE","EQUIPE RIVAL","RYWALE","RIVAAL TEAM","ECHIPĂ RIVALĂ","БРИГАДА ХАЛТУРЩИКОВ"),600,114,14,Color.WHITE,Paint.Align.LEFT,true);arcadeButton(c,action,t("TÁMADÁS","ATTACK","ANGRIFF","ATACAR","ATTAQUER","攻击","ATTACCA","ATACAR","ATAK","AANVAL","ATAC","АТАКА"),Color.rgb(132,47,41),false);}
  private void unit(Canvas c,float x,float y,int type,boolean enemy){int body=enemy?Color.rgb(117,54,45):(type==2?Color.rgb(85,92,104):type==1?Color.rgb(52,101,142):Color.rgb(139,113,61));fill(c,Color.rgb(38,42,44),x-9,y,x-2,y+20);fill(c,Color.rgb(38,42,44),x+3,y,x+10,y+20);fill(c,body,x-12,y-24,x+13,y+4);fill(c,Color.rgb(227,178,117),x-8,y-36,x+8,y-23);fill(c,enemy?Color.rgb(112,39,33):Color.rgb(228,174,48),x-10,y-40,x+10,y-34);if(type==1)line(c,Color.rgb(216,226,230),5,x+12,y-18,x+27,y-30);if(type==2){fill(c,Color.rgb(72,75,78),x-22,y-20,x-12,y+8);stroke(c,Color.rgb(184,184,176),2,x-22,y-20,x-12,y+8);} }
  private void bar(Canvas c,float x,float y,int v,int max,int col){fill(c,Color.rgb(30,30,33),x,y,x+240,y+16);fill(c,col,x+2,y+2,x+2+236*Math.max(0,v)/(float)max,y+14);stroke(c,Color.WHITE,1,x,y,x+240,y+16);}
  @Override void onGameDown(float x,float y){if(page==0){if(in(up,x,y))move(0,-1);else if(in(down,x,y))move(0,1);else if(in(left,x,y))move(-1,0);else if(in(right,x,y))move(1,0);else if(in(town,x,y))page=1;else if(in(combat,x,y))page=2;}else if(page==1&&in(action,x,y)){if(gold>=100){gold-=100;if(shop<=weld&&shop<=truck)shop++;else if(weld<=truck)weld++;else truck++;score+=100;owner.reportScore(score);}}else if(page==2&&in(action,x,y)){enemyHp-=28+weld*5;turn++;if(enemyHp>0)ownHp-=18;if(enemyHp<=0){gold+=180;score+=500;enemyHp=160+turn*10;ownHp=170;owner.reportScore(score);}if(ownHp<=0){ownHp=170;enemyHp=160;score=Math.max(0,score-100);}}invalidate();}
  private void move(int dx,int dy){hx=Math.max(0,Math.min(11,hx+dx));hy=Math.max(0,Math.min(8,hy+dy));for(Node n:nodes)if(!n.taken&&n.x==hx&&n.y==hy){n.taken=true;if(n.type==0)iron+=2;else if(n.type==1)cement+=2;else if(n.type==2)tools++;else gold+=60;score+=80;owner.reportScore(score);}}
  @Override void onGameMove(float x,float y){}@Override void onGameUp(float x,float y){}
}
